export class DomainError extends Error { constructor(code,status=400,details={}){super(code);this.code=code;this.status=status;this.details=details;} }
const fail=(code,status=400,details={})=>{throw new DomainError(code,status,details);};
const plain=x=>x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;
export const canonicalJSON=x=>JSON.stringify(sort(x));
