const bytes=x=>Buffer.byteLength(JSON.stringify(x),'utf8');
const clone=x=>structuredClone(x);
const eq=(a,b)=>canonicalJSON(a)===canonicalJSON(b);
const json=x=>JSON.parse(x);
const hash=x=>createHash('sha256').update(typeof x==='string'?x:canonicalJSON(x)).digest('hex');
const identifier=x=>typeof x==='string'&&/^[a-zA-Z0-9][a-zA-Z0-9_.:-]{0,199}$/.test(x);
const uuid=x=>typeof x==='string'&&/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(x);
